const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category='Todas', favorites=new Set();try{const v=JSON.parse(localStorage.getItem('knime-favorites')||'[]');if(Array.isArray(v))favorites=new Set(v)}catch(e){}
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function notify(s){$('#toast').textContent=s;setTimeout(()=>$('#toast').textContent='',2500)}
function persist(){try{localStorage.setItem('knime-favorites',JSON.stringify([...favorites]))}catch(e){notify('Favoritos disponíveis somente nesta sessão.')}}
function nav(){let options=['Todas','Favoritos',...CATEGORIES];$('#nav').innerHTML=options.map(c=>`<button data-category="${esc(c)}" class="${category===c?'active':''}" aria-pressed="${category===c}">${c==='Favoritos'?'★ ':''}${esc(c)}<span>${c==='Todas'?ENTRIES.length:c==='Favoritos'?favorites.size:ENTRIES.filter(e=>e.cat===c).length}</span></button>`).join('');$('#mobileCategory').innerHTML=options.map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}
function render(){const words=normalize($('#search').value.trim()).split(/\s+/).filter(Boolean);let items=ENTRIES.filter(e=>(category==='Todas'||(category==='Favoritos'?favorites.has(e.id):category===e.cat))&&words.every(w=>normalize([e.name,e.cat,e.desc,e.steps,e.tip,e.tags].join(' ')).includes(w)));if($('#sort').value==='az')items.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));$('#sectionTitle').textContent=category==='Todas'?'Todas as fichas':category;$('#results').textContent=`${items.length} ${items.length===1?'ficha encontrada':'fichas encontradas'}${words.length?' para sua busca':''}`;$('#grid').innerHTML=items.length?items.map(e=>`<article class="card glass"><span class="category">${esc(e.cat)}</span><button class="star ${favorites.has(e.id)?'saved':''}" data-star="${e.id}" aria-pressed="${favorites.has(e.id)}" aria-label="${favorites.has(e.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(e.name)}">${favorites.has(e.id)?'★':'☆'}</button><h3>${esc(e.name)}</h3><p>${esc(e.desc)}</p><div class="print-details"><b>Como usar:</b> ${esc(e.steps)}<br><b>Atenção:</b> ${esc(e.tip)}</div><div class="card-bottom"><button class="detail" data-detail="${e.id}">Consultar ficha <span aria-hidden="true">↗</span></button><span class="number">${String(e.id).padStart(3,'0')}</span></div></article>`).join(''):`<div class="empty"><h3>${category==='Favoritos'?'Sua coleção começa com uma estrela.':'Nenhuma ficha encontrada.'}</h3><p>${category==='Favoritos'?'Marque ★ nas fichas que você mais consulta.':'Tente outro termo ou selecione todas as categorias.'}</p><button class="button" id="reset">Ver todas as fichas</button></div>`;nav()}
function show(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
function shell(title,cat,body){return `<div class="modal-head"><div><span class="category">${esc(cat)}</span><h2 id="modalTitle">${esc(title)}</h2></div><button class="button" data-close aria-label="Fechar ficha">✕</button></div>${body}`}
const examples={rule:{title:'Rule Engine',code:'MISSING $idade$ => "Sem informação"\n$idade$ >= 18 => "Adulto"\nTRUE => "Menor de idade"',note:'Cria uma categoria a partir de idade. As regras são avaliadas em ordem; adapte a coluna ao seu schema.'},math:{title:'Math Formula',code:'$receita$ - $custo$',note:'Cria o resultado financeiro a partir de duas colunas numéricas. Confira a definição de custos e a unidade monetária.'},python:{title:'Python Script',code:'import knime.scripting.io as knio\n\ndf = knio.input_tables[0].to_pandas()\n# Exemplo: remover linhas inteiramente vazias\ndf = df.dropna(how="all")\nknio.output_tables[0] = knio.Table.from_pandas(df)',note:'Configure uma entrada e uma saída de tabela no Python Script. Requer KNIME Python Integration com pandas disponível.'},sql:{title:'Consulta SQL',code:'SELECT categoria, SUM(valor) AS total\nFROM vendas\nGROUP BY categoria\nORDER BY total DESC;',note:'Exemplo com tabela vendas e colunas categoria e valor. Ajuste nomes e sintaxe ao seu banco.'}};
let copyText='';document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.category){category=b.dataset.category;render()}if(b.dataset.query){category='Todas';$('#search').value=b.dataset.query;render()}if(b.dataset.star){const id=Number(b.dataset.star);favorites.has(id)?favorites.delete(id):favorites.add(id);persist();render()}if(b.dataset.detail){const e=ENTRIES.find(x=>x.id===Number(b.dataset.detail));copyText=`${e.name}\n${e.desc}\nComo usar: ${e.steps}\nAtenção: ${e.tip}`;show(shell(e.name,e.cat,`<p>${esc(e.desc)}</p><h4>Como usar</h4><p>${esc(e.steps)}</p><h4>Ponto de atenção</h4><div class="tip">${esc(e.tip)}</div><div class="modal-actions"><button class="button" data-copy>Copiar ficha</button><a class="button" href="https://hub.knime.com/search?query=${encodeURIComponent(e.name)}" target="_blank" rel="noopener">Buscar no KNIME Hub ↗</a></div>`))}if(b.dataset.example){const e=examples[b.dataset.example];copyText=e.code;show(shell(e.title,'Exemplo para copiar',`<p>${esc(e.note)}</p><pre class="snippet">${esc(e.code)}</pre><button class="button" data-copy>Copiar exemplo</button>`))}if(b.hasAttribute('data-close'))$('#modal').close();if(b.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(copyText);notify('Copiado para a área de transferência.')}catch(e){notify('Selecione o texto para copiá-lo.')}}if(b.id==='reset'){category='Todas';$('#search').value='';render()}if(b.id==='print')window.print()});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);$('#mobileCategory').addEventListener('change',e=>{category=e.target.value;render()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});
function themeLabel(){$('#theme').textContent=document.documentElement.dataset.theme==='dark'?'☀ Claro':'☾ Escuro'}$('#theme').addEventListener('click',()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('knime-theme',t)}catch(e){}themeLabel()});themeLabel();render();
